import {createPreviewService,deriveFinancials,derivePOStatus,itemStatusLabels,priceKindLabels} from './preview-workflow.js';
import {createPreviewFixtures} from './preview-fixtures.js';
import {validateItems,todayBangkok,money,poDate,monthLabel,paymentLabels} from './domain.js';
import {downloadPreviewReport,poStatusLabels} from './preview-export.js';

const root=document.querySelector('#app'),dialog=document.querySelector('#modal'),toast=document.querySelector('#toast');
if(!document.querySelector('link[data-preview-style]')){const link=document.createElement('link');link.rel='stylesheet';link.href='preview.css';link.dataset.previewStyle='true';document.head.append(link);}
const service=createPreviewService({fixtures:createPreviewFixtures()});
const actors={owner:{id:'preview-owner',role:'owner',display_name:'เจ้าของ · ทดลอง'},office:{id:'preview-office',role:'office',display_name:'พนักงาน · ทดลอง'},primary:{id:'preview-primary',role:'primary',can_export_report:true,display_name:'ฝ่ายจัดซื้อหลัก · ทดลอง'}};
let actor=actors.office,route='list',activeId='',draftItems=[],draftDate=todayBangkok(),reviewMode=false,month='2026-10',working=false,createCommandKey='',pendingRole=null,formDirty=false,pendingNavigation=null,editCommandKey='',listPage=0;
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const moneyText=cents=>`฿${money(cents)}`;
const reasonFor=item=>item.return_reason||item.reject_reason||item.revision_reason||'';
const fieldLabels={department:'แผนก/สาขา',name:'ชื่อสินค้า',spec:'รายละเอียด / สเปค',source:'แหล่งซื้อ',note:'หมายเหตุ',payment_method:'การชำระเงิน',qty:'จำนวน',unit:'หน่วย',unit_price:'ราคาต่อหน่วย',vat:'ประเภทภาษี',price_kind:'ชนิดราคา'};
const displaySnapshotValue=(key,value)=>key==='unit_price'?moneyText(Math.round(Number(value)*100)):key==='payment_method'?paymentLabels[value]||'ไม่ระบุ':key==='vat'?value?'VAT 7%':'NON VAT':key==='price_kind'?priceKindLabels[value]||value:String(value??'—');
const notify=text=>{toast.textContent=text;toast.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>toast.classList.remove('visible'),3200);};
const currentPO=()=>activeId?service.load(activeId,actor):null;
const statusLabel=status=>poStatusLabels[status]||status;
const field=(label,name,value='',type='text',attrs='')=>`<label class="preview-field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const textarea=(label,name,value='',attrs='')=>`<label class="preview-field preview-wide"><span>${label}</span><textarea name="${name}" ${attrs}>${esc(value)}</textarea></label>`;
function appShell(body){root.innerHTML=`<div class="preview-shell"><header class="preview-top"><a class="preview-brand" href="#" data-nav="list"><img src="favicon.svg" alt=""><span>PO The Grands</span></a><div class="preview-switch"><span class="preview-label">สลับบทบาทสำหรับสาธิต</span><div class="preview-switch-buttons">${[['owner','ทดลองเป็นเจ้าของ'],['office','ทดลองเป็นพนักงาน'],['primary','ทดลองเป็นจัดซื้อหลัก']].map(([key,label])=>`<button type="button" class="${actor.role===key?'selected':''}" aria-pressed="${actor.role===key}" data-role="${key}">${label}</button>`).join('')}</div></div><div class="preview-user"><strong>${esc(actor.display_name)}</strong><button class="ghost" type="button" data-action="reset">เริ่มชุดตัวอย่างใหม่</button></div></header><aside class="preview-notice" role="note"><strong>โหมดทดลอง</strong><span>ใช้ข้อมูลสังเคราะห์ที่บันทึกไว้เฉพาะเบราว์เซอร์นี้ ทุกการอนุมัติและยอดเงินไม่มีผลกับใบ PO จริง</span><label class="preview-fixture"><span>เปิดสถานการณ์ตัวอย่าง</span><select aria-label="เปิดสถานการณ์ตัวอย่าง" id="fixture-select"><option value="">เลือกรายการตัวอย่าง</option>${service.list(actor).map(po=>`<option value="${esc(po.id)}" ${activeId===po.id?'selected':''}>${esc(po.po_number)} · ${esc(po.items[0]?.name||'')}</option>`).join('')}</select></label></aside><nav class="preview-nav" aria-label="เมนูหลัก"><button type="button" data-nav="list" aria-current="${route==='list'?'page':'false'}">ใบ PO ทดลอง</button>${canAuthor()?`<button type="button" data-nav="create" aria-current="${route==='create'?'page':'false'}">เปิดใบ PO</button>`:''}${actor.role==='primary'?`<button type="button" data-nav="report" aria-current="${route==='report'?'page':'false'}">รายงานรวม</button>`:''}</nav><main class="preview-main">${body}</main><footer class="preview-footer">PO The Grands · ชุดทดลองในเครื่องนี้ · ไม่เชื่อมต่อฐานข้อมูลจริง</footer></div>`;}
function canAuthor(po=null){return ['office','primary'].includes(actor.role)&&(!po||po.created_by===actor.id);}
function canReceive(po){return ['office','primary'].includes(actor.role)&&(actor.role==='primary'||po.created_by===actor.id);}
function metric(title,value,sub=''){return `<article class="preview-metric"><span>${title}</span><strong>${value}</strong>${sub?`<small>${sub}</small>`:''}</article>`;}
function statusCounts(rows){const counts={pending:0,returned:0,rejected:0,budget_approved:0,approved:0,revision_requested:0,editing:0,received:0};rows.forEach(po=>po.items.forEach(item=>{counts[item.state]=(counts[item.state]||0)+1;}));return counts;}
function renderList(){route='list';const rows=service.list(actor).sort((a,b)=>b.created_at.localeCompare(a.created_at)),counts=statusCounts(rows),summary=rows.reduce((sum,po)=>{const f=deriveFinancials(po);sum.confirmed+=f.confirmed_purchase_cents;sum.budget+=f.budget_authorized_cents;return sum;},{confirmed:0,budget:0});const pageSize=10,pageCount=Math.max(1,Math.ceil(rows.length/pageSize));listPage=Math.min(listPage,pageCount-1);const shownRows=rows.slice(listPage*pageSize,(listPage+1)*pageSize);const body=`<div class="preview-heading"><div><div class="eyebrow">DEMO WORKSPACE · ${actor.role==='owner'?'OWNER':actor.role==='primary'?'PRIMARY OFFICE':'OFFICE'}</div><h1>ใบ PO ทดลอง</h1><p>ติดตามและดำเนินการแยกตามรายการสินค้า</p></div>${canAuthor()?`<button class="primary" type="button" data-nav="create">เปิดใบ PO</button>`:''}</div><section class="preview-metrics" aria-label="สรุปสถานะรายการ">${metric('รออนุมัติหรือแก้ไข',counts.pending+counts.returned+counts.revision_requested+counts.editing)}${metric('อนุมัติซื้อแล้ว',counts.approved)}${metric('วงเงินประมาณการ',moneyText(summary.budget))}${metric('ยอดซื้อยืนยันแล้ว',moneyText(summary.confirmed))}${metric('ไม่อนุมัติ',counts.rejected)}</section><section class="preview-panel"><div class="preview-panel-head"><div><h2>ใบ PO ทั้งหมด</h2><p>${rows.length} ใบ · แสดงทุกสถานะรายการ</p></div><button type="button" data-action="refresh">โหลดข้อมูลล่าสุด</button></div>${rows.length?`<div class="preview-table-wrap"><table class="preview-table"><thead><tr><th>เลขที่ / วันที่</th><th>ผู้ขอ</th><th>สถานะปัจจุบัน</th><th>รายการ</th><th>ยอดซื้อยืนยัน</th><th></th></tr></thead><tbody>${shownRows.map(po=>`<tr><td><strong>${esc(po.po_number)}</strong><small>${esc(poDate(po.po_date))}</small></td><td>${esc(po.requester_name)}</td><td><span class="preview-status">${esc(statusLabel(po.status))}</span></td><td>${po.items.map(item=>`<div class="preview-item-line"><span>${esc(item.name)}</span><small>${esc(itemStatusLabels[item.state])}</small></div>`).join('')}</td><td>${moneyText(po.confirmed_purchase_cents)}<small>วงเงิน ${moneyText(po.budget_authorized_cents)}</small></td><td><button type="button" class="preview-open" data-open="${esc(po.id)}" aria-label="เปิดใบ PO ${esc(po.po_number)}">เปิดดู</button></td></tr>`).join('')}</tbody></table></div>${pageCount>1?`<div class="preview-pagination"><button type="button" data-page="${listPage-1}" ${listPage===0?'disabled':''}>ก่อนหน้า</button><span>หน้า ${listPage+1} จาก ${pageCount}</span><button type="button" data-page="${listPage+1}" ${listPage>=pageCount-1?'disabled':''}>ถัดไป</button></div>`:''}`:`<div class="preview-empty"><strong>ยังไม่มีรายการทดลอง</strong><p>เปิดใบ PO ใหม่เพื่อเริ่มดูขั้นตอนอนุมัติ</p>${canAuthor()?`<button type="button" class="primary" data-nav="create">เปิดใบ PO</button>`:''}</div>`}</section>`;appShell(body);}
function itemActions(po,item){const name=esc(item.name),itemId=esc(item.id),button=(action,label,kind='')=>`<button type="button" class="${kind}" data-item-action="${action}" data-item-id="${itemId}" aria-label="${label} · ${name}">${label}</button>`,editButton=()=>button('edit','แก้ไขและส่งอนุมัติอีกครั้ง');if(po.closed_at)return `<p class="preview-muted">ใบ PO ปิดแล้ว · แก้ไขรายการไม่ได้</p>`;if(actor.role==='owner'){if(item.state==='pending'){return `<div class="preview-actions">${button(item.price_kind==='estimated'?'approve_estimate':'approve',item.price_kind==='estimated'?'อนุมัติวงเงินประมาณการ':'อนุมัติซื้อ','primary')}${button('return','ส่งกลับพร้อมเหตุผล')}${button('reject','ไม่อนุมัติ','danger')}</div>`;}if(['approved','budget_approved'].includes(item.state))return `<div class="preview-actions">${button('return_edit','ขอแก้ไขและพักการอนุมัติ','danger')}${item.state==='budget_approved'?`<small>วงเงินนี้ยังไม่ใช่ยอดซื้อ และรอพนักงานยืนยันราคาจริง</small>`:''}</div>`;if(item.state==='revision_requested')return `<div class="preview-actions">${button('unlock','ปลดล็อกให้แก้ไข','primary')}${button('refuse_revision','ไม่รับคำขอ · คงผลอนุมัติเดิม')}</div>`;return `<p class="preview-muted">${item.state==='received'?'รับแล้ว · แก้ไขรายการไม่ได้':item.state==='rejected'?'รายการสิ้นสุดแล้ว':item.state==='editing'?'รอพนักงานแก้ไข':'ไม่มีการดำเนินการสำหรับสถานะนี้'}</p>`;}
 if(['returned','editing','budget_approved'].includes(item.state)){return canAuthor(po)?`<div class="preview-actions">${editButton()}${item.state==='budget_approved'?`${button('request_revision','ขอแก้ไขรายการ · พักการอนุมัติ','danger')}<small>ต้องยืนยันราคาจริงและส่งให้เจ้าของอนุมัติใหม่ก่อนสั่งซื้อ</small>`:''}</div>`:`<p class="preview-muted">${item.state==='budget_approved'?'รอผู้สร้างยืนยันราคา':'รอผู้สร้างแก้ไขรายการ'}</p>`;}const actions=[];if(['approved','budget_approved'].includes(item.state)&&canAuthor(po))actions.push(button('request_revision','ขอแก้ไขรายการ · พักการอนุมัติ','danger'));if(item.state==='approved'&&canReceive(po))actions.push(button('receive','ยืนยันรับสินค้ารายการนี้','primary'));if(actions.length)return `<div class="preview-actions">${actions.join('')}</div>`;return `<p class="preview-muted">${item.state==='received'?'รับแล้ว · แก้ไขรายการไม่ได้':item.state==='rejected'?'รายการสิ้นสุดแล้ว':'รอเจ้าของดำเนินการ'}</p>`;}
function itemCard(po,item){return `<article class="preview-item-card"><div class="preview-item-top"><div><span class="preview-status preview-status-${esc(item.state)}">${esc(itemStatusLabels[item.state]||item.state)}</span><h3>${esc(item.name)}</h3><p>${esc(item.spec)}</p>${item.note?`<p class="preview-item-note"><strong>หมายเหตุ:</strong> ${esc(item.note)}</p>`:''}</div><div class="preview-money"><strong>${moneyText(item.total_cents)}</strong><small>${esc(priceKindLabels[item.price_kind])} · ${item.vat?'VAT 7%':'NON VAT'}</small></div></div><dl class="preview-detail-grid"><div><dt>แผนก/สาขา</dt><dd>${esc(item.department)}</dd></div><div><dt>แหล่งซื้อ</dt><dd>${esc(item.source)}</dd></div><div><dt>จำนวน / หน่วย</dt><dd>${esc(item.qty)} ${esc(item.unit)}</dd></div><div><dt>ราคาต่อหน่วย</dt><dd>${moneyText(Math.round(Number(item.unit_price)*100))}</dd></div><div><dt>การชำระเงิน</dt><dd>${esc(paymentLabels[item.payment_method]||'ไม่ระบุ')}</dd></div><div><dt>หมายเหตุ</dt><dd>${esc(item.note||'—')}</dd></div><div><dt>ก่อน VAT / VAT</dt><dd>${moneyText(item.base_cents)} / ${moneyText(item.tax_cents)}</dd></div></dl>${reasonFor(item)?`<p class="preview-reason"><strong>เหตุผลล่าสุด:</strong> ${esc(reasonFor(item))}</p>`:''}${item.approved_snapshot?`<details class="preview-snapshot"><summary>ดูข้อมูลที่อนุมัติเดิม</summary><dl>${Object.entries(item.approved_snapshot).filter(([key])=>!['id','revision','base_cents','tax_cents','total_cents'].includes(key)).map(([key,value])=>`<div><dt>${esc(fieldLabels[key]||key)}</dt><dd>${esc(displaySnapshotValue(key,value))}</dd></div>`).join('')}<div><dt>ยอดรวมเดิม</dt><dd>${moneyText(item.approved_snapshot.total_cents)}</dd></div></dl></details>`:''}<div class="preview-item-actions">${itemActions(po,item)}</div></article>`;}
function eventLabel(event){return ({create:'เปิดใบ PO',approve:'อนุมัติซื้อ',approve_estimate:'อนุมัติวงเงินประมาณการ',return:'ส่งกลับแก้ไข',return_edit:'ขอแก้ไขและพักการอนุมัติ',reject:'ไม่อนุมัติ',confirm_price:'ยืนยันราคา',request_revision:'ขอแก้ไขและพักการอนุมัติ',unlock:'ปลดล็อกแก้ไข',refuse_revision:'ปฏิเสธคำขอแก้ไข · คงอนุมัติเดิม',resubmit:'ส่งขออนุมัติใหม่',edit:'แก้ไขรายการ',receive:'รับสินค้า',close:'ปิดใบ PO'}[event.action]||event.action);}
function timeline(po){return `<section class="preview-panel"><h2>ประวัติการดำเนินการ</h2><ol class="preview-timeline">${po.events.map(event=>`<li><div><strong>${esc(eventLabel(event))}${event.item_name?` · ${esc(event.item_name)}`:''}</strong><span>${esc(event.actor_name)} · ${esc(new Intl.DateTimeFormat('th-TH',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Bangkok'}).format(new Date(event.at)))}</span>${event.reason?`<p>${esc(event.reason)}</p>`:''}${event.before&&event.after?`<details class="preview-diff"><summary>ดูข้อมูลก่อนและหลังแก้ไข · ผลต่าง ${moneyText(event.delta_cents)}</summary><div class="preview-diff-grid"><section><h3>ก่อนแก้ไข</h3><dl>${Object.entries(event.before).filter(([key])=>!['id','revision','base_cents','tax_cents'].includes(key)).map(([key,value])=>`<div><dt>${esc(fieldLabels[key]||'ยอดรวม')}</dt><dd>${esc(key==='total_cents'?moneyText(value):displaySnapshotValue(key,value))}</dd></div>`).join('')}</dl></section><section><h3>หลังแก้ไข</h3><dl>${Object.entries(event.after).filter(([key])=>!['id','revision','base_cents','tax_cents'].includes(key)).map(([key,value])=>`<div><dt>${esc(fieldLabels[key]||'ยอดรวม')}</dt><dd>${esc(key==='total_cents'?moneyText(value):displaySnapshotValue(key,value))}</dd></div>`).join('')}</dl></section></div></details>`:''}</div></li>`).join('')}</ol></section>`;}
function renderDetail(){route='detail';const po=currentPO();if(!po){renderList();return;}const closeReady=po.items.some(i=>i.state==='received')&&po.items.every(i=>['received','rejected'].includes(i.state));const closeButton=actor.role==='owner'&&!po.closed_at?`<section class="preview-panel preview-close-panel"><div><h2>ปิดใบ PO</h2><p>${closeReady?'ทุกรายการรับแล้วหรือไม่อนุมัติ เหลือยืนยันใบกำกับภาษี':'ปิดได้เมื่อทุกรายการรับแล้วหรือไม่อนุมัติ และมีอย่างน้อยหนึ่งรายการรับแล้ว'}</p></div><button class="primary" type="button" data-action="close" ${closeReady?'':'disabled'}>ยืนยันใบกำกับภาษีและปิด</button></section>`:'';const body=`<div class="preview-heading"><div><button type="button" class="ghost preview-back" data-nav="list">← กลับรายการ</button><div class="eyebrow">PURCHASE ORDER · ${esc(po.po_number)}</div><h1>${esc(po.po_number)}</h1><p>${esc(poDate(po.po_date))} · ผู้ขอ ${esc(po.requester_name)} · รุ่นข้อมูล ${po.version}</p></div><span class="preview-status preview-status-large">${esc(statusLabel(po.status))}</span></div><section class="preview-metrics preview-detail-metrics">${metric('ยอดส่งขออนุมัติ',moneyText(po.submitted_total_cents))}${metric('วงเงินประมาณการ',moneyText(po.budget_authorized_cents),'ยังไม่นับเป็นยอดซื้อ')}${metric('ยอดซื้อยืนยัน',moneyText(po.confirmed_purchase_cents),'ราคาอนุมัติแล้วหรือรับแล้ว')}${metric('รับสินค้าแล้ว',moneyText(po.received_cents))}</section><section><div class="preview-section-heading"><div><h2>รายการสินค้า</h2><p>การอนุมัติและการรับสินค้าแยกกันในแต่ละรายการ</p></div></div><div class="preview-item-list">${po.items.map(item=>itemCard(po,item)).join('')}</div></section>${closeButton}${timeline(po)}`;appShell(body);}
function itemFormMarkup(item={},index=0,editMode=false){const value={department:'',name:'',spec:'',source:'',note:'',qty:'1',unit:'',unit_price:'',vat:true,payment_method:'',price_kind:'confirmed',...item};const disabled=working?'disabled':'',radioName=`payment_method-${index}`;return `<fieldset class="preview-form-item"><legend>${editMode?'แก้ไขรายการ':'รายการสินค้า '+(index+1)}</legend><div class="preview-form-grid">${field('ชื่อสินค้า','name',value.name,'text','required maxlength="200"')}${field('แผนก/สาขา','department',value.department,'text','required maxlength="100"')}${textarea('รายละเอียด / สเปค','spec',value.spec,'required maxlength="2000"')}${field('แหล่งซื้อ','source',value.source,'text','required maxlength="300"')}${field('จำนวน','qty',value.qty,'number','required min="0.001" step="0.001"')}${field('หน่วย','unit',value.unit,'text','required maxlength="50"')}${field('ราคาต่อหน่วย (บาท)','unit_price',value.unit_price,'number','required min="0.01" step="0.01"')}${field('หมายเหตุ','note',value.note,'text','maxlength="2000"')}<label class="preview-field"><span>ประเภท VAT</span><select name="vat"><option value="true" ${value.vat?'selected':''}>VAT 7%</option><option value="false" ${!value.vat?'selected':''}>NON VAT</option></select></label><label class="preview-field"><span>ราคา</span><select name="price_kind" required><option value="confirmed" ${value.price_kind==='confirmed'?'selected':''}>ราคายืนยันแล้ว</option><option value="estimated" ${value.price_kind==='estimated'?'selected':''}>ราคาประมาณการ</option></select></label><fieldset class="preview-payment"><legend>การชำระเงิน</legend><label><input type="radio" name="${radioName}" value="credit" ${value.payment_method==='credit'?'checked':''} required> เครดิต</label><label><input type="radio" name="${radioName}" value="cash" ${value.payment_method==='cash'?'checked':''} required> เงินสด</label></fieldset></div>${!editMode&&draftItems.length>1?`<button type="button" class="ghost danger" data-remove-line="${index}" ${disabled}>ลบรายการ ${index+1}</button>`:''}</fieldset>`;}
function collectForm(form){const value=name=>form.querySelector(`[name="${name}"]`)?.value??'';return {department:value('department'),name:value('name'),spec:value('spec'),source:value('source'),note:value('note')||'',qty:value('qty'),unit:value('unit'),unit_price:value('unit_price'),vat:value('vat')==='true',payment_method:form.querySelector('input[type="radio"]:checked')?.value||'',price_kind:value('price_kind')};}
function setError(form,message,target=null){let box=form.querySelector('[data-form-error]');if(!box){box=document.createElement('div');box.dataset.formError='';box.className='preview-error';box.setAttribute('role','alert');form.prepend(box);}if(!box.id)box.id=`preview-error-${crypto.randomUUID()}`;box.textContent=message;const stale=/ข้อมูลเปลี่ยนแล้ว|ข้อมูลถูกแก้ไขแล้ว|รุ่นข้อมูล|เวอร์ชัน/i.test(message);if(stale&&!box.querySelector('[data-action="reload-latest"]')){const reload=document.createElement('button');reload.type='button';reload.dataset.action='reload-latest';reload.textContent='โหลดข้อมูลล่าสุด';box.append(reload);}const field=target||form.querySelector(':invalid')||form.querySelector('input:not([type=hidden]),select,textarea');if(field){field.setAttribute('aria-invalid','true');field.setAttribute('aria-describedby',box.id);field.focus();}}
function clearFieldError(form,target){target.removeAttribute('aria-invalid');const error=form.querySelector('[data-form-error]');if(error){if(target.getAttribute('aria-describedby')===error.id)target.removeAttribute('aria-describedby');error.remove();}}
function requestNavigation(callback,onCancel=()=>{}){if(!formDirty){callback();return;}pendingNavigation=callback;dialog.innerHTML=`<form method="dialog" novalidate class="preview-dialog-form"><h2 id="modal-title">ทิ้งการแก้ไขที่ยังไม่ส่ง?</h2><p>ข้อมูลในแบบฟอร์มยังไม่บันทึก หากออกจากหน้านี้จะลบทิ้ง</p><div class="preview-form-actions"><button type="button" data-dialog-cancel data-cancel-navigation autofocus>กลับไปแก้ไข</button><button type="button" class="danger" data-action="discard-navigation">ทิ้งการแก้ไข</button></div></form>`;dialog.showModal();dialog.querySelector('[data-cancel-navigation]').addEventListener('click',()=>{onCancel();});}
function renderCreate(){route='create';reviewMode=false;draftItems=draftItems.length?draftItems:[{}];const body=`<div class="preview-heading"><div><button type="button" class="ghost preview-back" data-nav="list">← กลับรายการ</button><div class="eyebrow">OFFICE · DEMO ONLY</div><h1>เปิดใบ PO ทดลอง</h1><p>กรอกข้อมูลและตรวจรายการก่อนส่งให้เจ้าของ</p></div></div><form class="preview-panel" id="preview-create-form" novalidate><div class="preview-form-grid">${field('วันที่ PO','po_date',draftDate,'date','required')}</div><div class="preview-lines">${draftItems.map((item,index)=>itemFormMarkup(item,index)).join('')}</div><div class="preview-form-actions"><button type="button" data-action="add-line">เพิ่มรายการสินค้า</button><button type="submit" class="primary">ตรวจสอบก่อนส่ง</button></div></form>`;appShell(body);const form=root.querySelector('#preview-create-form');form.addEventListener('submit',event=>{event.preventDefault();try{draftDate=form.querySelector('[name="po_date"]').value;if(!draftDate)throw Error('เลือกวันที่ใบ PO');const inputs=[...form.querySelectorAll('fieldset.preview-form-item')];draftItems=inputs.map(fs=>collectForm(fs));draftItems=draftItems.map(awaitValidate);reviewMode=true;formDirty=true;createCommandKey=crypto.randomUUID();renderReview();}catch(error){setError(form,error.message);}});}
function awaitValidate(item){const [valid]=validateItems([item]);if(!item.department||!item.unit||!item.payment_method||!item.price_kind)throw Error('กรอกแผนก หน่วย ราคา และการชำระเงินให้ครบ');return {...valid,price_kind:item.price_kind};}
function renderReview(){route='review';const items=draftItems.map(awaitValidate);const rows=items.map(item=>`<tr><td>${esc(item.name)}<small>${esc(item.spec)}</small><small>แหล่งซื้อ: ${esc(item.source)}</small><small>หมายเหตุ: ${esc(item.note||'—')}</small></td><td>${esc(item.department)} · ${esc(item.qty)} ${esc(item.unit)}</td><td>${esc(priceKindLabels[item.price_kind])}<small>${moneyText(Math.round(Number(item.unit_price)*100))} / หน่วย</small><small>${item.vat?'VAT 7%':'NON VAT'}</small><small>${esc(paymentLabels[item.payment_method]||'ไม่ระบุ')}</small></td><td>${moneyText(item.total_cents)}</td></tr>`).join(''),sum=items.reduce((n,item)=>n+item.total_cents,0);const body=`<div class="preview-heading"><div><div class="eyebrow">REVIEW BEFORE SUBMIT</div><h1>ตรวจสอบใบ PO ก่อนส่ง</h1><p>${esc(poDate(draftDate))} · ${items.length} รายการ</p></div></div><section class="preview-panel"><div class="preview-table-wrap"><table class="preview-table"><thead><tr><th>สินค้า / แหล่งซื้อ / หมายเหตุ</th><th>แผนก / จำนวน</th><th>ราคา / ภาษี / ชำระ</th><th>ยอดรวม</th></tr></thead><tbody>${rows}</tbody></table></div><div class="preview-total">ยอดส่งขออนุมัติ <strong>${moneyText(sum)}</strong></div><div class="preview-form-actions"><button type="button" data-action="back-to-edit">ย้อนกลับแก้ไข</button><button type="button" class="primary" data-action="submit-create">ส่งให้เจ้าของพิจารณา</button></div><p class="preview-muted">ใบ PO จะบันทึกในเบราว์เซอร์นี้เท่านั้น</p></section>`;appShell(body);}
function renderEdit(item,po){route='edit';formDirty=false;editCommandKey=crypto.randomUUID();const displayedVersion=po.version,isBudget=item.state==='budget_approved',initial={...item};if(isBudget)initial.price_kind='confirmed';const body=`<div class="preview-heading"><div><button type="button" class="ghost preview-back" data-open="${esc(po.id)}">← กลับใบ PO</button><div class="eyebrow">แก้ไขรายการ · ${esc(item.name)}</div><h1>${isBudget?'ยืนยันราคาจริงและส่งอนุมัติใหม่':'แก้ไขรายการและส่งให้เจ้าของพิจารณา'}</h1><p>ค่าก่อนแก้ไขจะเก็บไว้ในประวัติอย่างถาวร</p></div></div><form class="preview-panel" id="preview-edit-form" novalidate>${itemFormMarkup(initial,0,true)}<div class="preview-form-actions"><button type="button" data-open="${esc(po.id)}">ยกเลิก</button><button type="submit" class="primary">${isBudget?'ยืนยันราคาและส่งขออนุมัติ':'บันทึกและส่งขออนุมัติใหม่'}</button></div></form>`;appShell(body);const form=root.querySelector('#preview-edit-form');form.addEventListener('submit',event=>{event.preventDefault();try{const next=awaitValidate(collectForm(form));service.edit(po.id,item.id,next,{actor,reason:'แก้ไขตามคำขอในโหมดทดลอง',key:editCommandKey,expectedVersion:displayedVersion,submit:true});formDirty=false;activeId=po.id;notify(isBudget?'ยืนยันราคาแล้ว ส่งให้เจ้าของอนุมัติใหม่':'แก้ไขแล้ว ส่งให้เจ้าของอนุมัติใหม่');renderDetail();}catch(error){setError(form,error.message);}});}
function renderReport(){route='report';if(actor.role!=='primary'){renderList();return;}const report=service.report(month,actor);const body=`<div class="preview-heading"><div><div class="eyebrow">PRIMARY OFFICE · SYNTHETIC DATA</div><h1>รายงานรวมเพื่อการทดลอง</h1><p>ยอดซื้อเฉพาะรายการราคายืนยันที่อนุมัติแล้วหรือรับแล้ว</p></div></div><section class="preview-panel"><div class="preview-report-controls"><label class="preview-field"><span>เดือนที่รายงาน</span><input type="month" id="preview-month" value="${esc(month)}"></label><button type="button" class="primary" data-action="export">ส่งออก Excel</button></div><p class="preview-report-note">ยอดซื้อยืนยัน <strong>${moneyText(report.total_cents)}</strong> · วงเงินประมาณการ <strong>${moneyText(report.budget_authorized_cents)}</strong> (ไม่นับเป็นยอดซื้อ) · รออนุมัติ/แก้ไข ${report.pending_count} รายการ · ไม่อนุมัติ ${report.rejected_count} รายการ</p><div class="preview-table-wrap"><table class="preview-table"><thead><tr><th>ใบ PO</th><th>สินค้า</th><th>สถานะรายการ</th><th>ชนิดราคา</th><th>ยอดรวม</th><th>นับในยอดซื้อ</th></tr></thead><tbody>${report.rows.flatMap(po=>po.items.map(item=>`<tr><td><button class="preview-link" data-open="${esc(po.id)}">${esc(po.po_number)}</button></td><td>${esc(item.name)}</td><td>${esc(itemStatusLabels[item.state])}</td><td>${esc(priceKindLabels[item.price_kind])}</td><td>${moneyText(item.total_cents)}</td><td>${['approved','received'].includes(item.state)&&item.price_kind==='confirmed'?moneyText(item.total_cents):moneyText(0)}</td></tr>`)).join('')}</tbody></table></div></section>`;appShell(body);root.querySelector('#preview-month').addEventListener('change',event=>{month=event.target.value||'2026-10';renderReport();});}
function render(){if(route==='detail')renderDetail();else if(route==='create')renderCreate();else if(route==='review')renderReview();else if(route==='edit'){const po=currentPO();if(!po)renderList();}else if(route==='report')renderReport();else renderList();}
function reasonDialog(title,item,action,{invoice=false,receive=false}={}){const needsReason=['return','reject','return_edit','request_revision','refuse_revision'].includes(action),optionalReason=['approve','approve_estimate'].includes(action),openedPO=currentPO(),expectedVersion=openedPO.version,key=crypto.randomUUID();dialog.innerHTML=`<form method="dialog" novalidate class="preview-dialog-form" id="preview-action-form"><h2 id="modal-title">${esc(title)}</h2><p>รายการ: <strong>${esc(item?.name||'ทั้งใบ PO')}</strong></p>${invoice?`<label class="preview-confirm"><input type="checkbox" name="invoice"> ยืนยันว่าได้รับใบกำกับภาษีของใบ PO นี้แล้ว</label>`:''}${receive?`<label class="preview-confirm"><input type="checkbox" name="received"> ยืนยันว่าได้รับสินค้ารายการนี้ครบแล้ว</label>`:''}${needsReason?textarea('เหตุผล (จำเป็น)','reason','','required maxlength="2000"'):optionalReason?textarea('หมายเหตุถึงผู้ขอ (ไม่บังคับ)','reason','','maxlength="2000"'):'<div class="preview-field"><span>ตรวจสอบชื่อรายการและผลที่จะเกิดขึ้นก่อนยืนยัน</span></div>'}<div class="preview-dialog-error" role="alert" data-form-error></div><div class="preview-form-actions"><button type="button" data-dialog-cancel autofocus>กลับ</button><button class="primary" type="submit">${esc(action==='reject'?'ไม่อนุมัติ':action==='return'?'ส่งกลับพร้อมเหตุผล':action==='return_edit'?'พักการอนุมัติ':action==='request_revision'?'ส่งคำขอแก้ไข':action==='refuse_revision'?'คงการอนุมัติเดิม':action==='close'?'ยืนยันใบกำกับภาษีและปิด':action==='receive'?'ยืนยันรับสินค้า':'ยืนยัน')}</button></div></form>`;dialog.showModal();const form=dialog.querySelector('form');form.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(form),reason=String(data.get('reason')||'').trim();if(needsReason&&!reason){const textareaEl=form.querySelector('[name=reason]');setError(form,'ระบุเหตุผลก่อนทำรายการ',textareaEl);return;}if(reason.length>2000){setError(form,'เหตุผลต้องไม่เกิน 2,000 ตัวอักษร',form.querySelector('[name=reason]'));return;}if(invoice&&!data.get('invoice')){setError(form,'ยืนยันว่าได้รับใบกำกับภาษีก่อนปิดใบ PO',form.querySelector('[name=invoice]'));return;}if(receive&&!data.get('received')){setError(form,'ยืนยันว่าได้รับสินค้ารายการนี้ครบแล้ว',form.querySelector('[name=received]'));return;}void performAction(action,item,reason,{invoice:Boolean(data.get('invoice')),receive:Boolean(data.get('received')),expectedVersion,key}).catch(error=>setError(form,error.message));});}
async function performAction(action,item,reason,{invoice=false,receive=false,expectedVersion,key}={}){if(working)return;working=true;const po=currentPO();try{if(action==='edit'){renderEdit(item,po);return;}if(action==='close')service.run(po.id,'close',{actor,itemId:null,reason,confirmed:invoice,key,expectedVersion});else service.run(po.id,action,{actor,itemId:item.id,reason,confirmed:receive,key,expectedVersion});dialog.close();notify(action==='approve_estimate'?'อนุมัติวงเงินประมาณการแล้ว':action==='approve'?'อนุมัติรายการแล้ว':action==='receive'?'บันทึกรับสินค้าแล้ว':action==='close'?'ปิดใบ PO แล้ว':'บันทึกการดำเนินการแล้ว');renderDetail();}finally{working=false;}}
function confirmReset(){dialog.innerHTML=`<form method="dialog" novalidate class="preview-dialog-form"><h2 id="modal-title">เริ่มชุดตัวอย่างใหม่?</h2><p>ล้างเฉพาะรายการทดลองที่บันทึกไว้ในเบราว์เซอร์นี้ แล้วคืนข้อมูลสังเคราะห์เริ่มต้น</p><div class="preview-form-actions"><button type="button" data-dialog-cancel autofocus>กลับ</button><button type="button" class="danger" data-action="reset-confirm">ล้างข้อมูลทดลอง</button></div></form>`;dialog.showModal();}
let lastDialogTrigger=null;
const originalShowModal=dialog.showModal.bind(dialog);
dialog.showModal=()=>{lastDialogTrigger=document.activeElement;originalShowModal();};
function activateRole(key){actor=actors[key];formDirty=false;draftItems=[];if(route==='detail'&&!service.list(actor).some(po=>po.id===activeId))route='list';else if(['create','review','edit'].includes(route))route=activeId&&service.list(actor).some(po=>po.id===activeId)?'detail':'list';if(route==='report'&&actor.role!=='primary')route='list';render();}
function navigateTo(target){requestNavigation(()=>{if(target==='create'){draftItems=[{}];draftDate=todayBangkok();createCommandKey='';}formDirty=false;route=target;render();});}
window.addEventListener('beforeunload',event=>{if(formDirty){event.preventDefault();event.returnValue='';}});
root.addEventListener('input',event=>{if(event.target.closest('#preview-create-form,#preview-edit-form')){formDirty=true;clearFieldError(event.target.form,event.target);}});
root.addEventListener('change',event=>{if(event.target.id==='fixture-select'){const id=event.target.value,old=activeId;if(!id)return;requestNavigation(()=>{formDirty=false;activeId=id;renderDetail();},()=>{const select=root.querySelector('#fixture-select');if(select)select.value=old;});return;}if(event.target.closest('#preview-create-form,#preview-edit-form'))formDirty=true;});
root.addEventListener('click',event=>{
 const roleButton=event.target.closest('[data-role]');if(roleButton){const key=roleButton.dataset.role;if(key===actor.role)return;requestNavigation(()=>activateRole(key));return;}
 const nav=event.target.closest('[data-nav]');if(nav){const target=nav.dataset.nav;if(target==='create'&&!canAuthor()){notify('เปิดใบ PO ได้เฉพาะบทบาทพนักงานทดลอง');return;}if(target==='report'&&actor.role!=='primary'){notify('รายงานรวมเปิดได้เฉพาะฝ่ายจัดซื้อหลักในโหมดทดลอง');return;}navigateTo(target);return;}
 const open=event.target.closest('[data-open]');if(open){const id=open.dataset.open;requestNavigation(()=>{formDirty=false;activeId=id;renderDetail();});return;}
 const actionButton=event.target.closest('[data-action]');if(actionButton){const action=actionButton.dataset.action;
  if(action==='refresh'){renderList();notify('โหลดข้อมูลทดลองล่าสุดแล้ว');return;}
  if(action==='reload-latest'){formDirty=false;dialog.close();renderDetail();notify('โหลดข้อมูลล่าสุดแล้ว แบบฟอร์มที่ยังไม่ส่งถูกทิ้ง');return;}
  if(action==='reset'){requestNavigation(confirmReset);return;}
  if(action==='add-line'){const form=root.querySelector('#preview-create-form');draftDate=form.querySelector('[name="po_date"]').value;draftItems=[...form.querySelectorAll('fieldset.preview-form-item')].map(fs=>collectForm(fs));draftItems.push({});formDirty=true;renderCreate();return;}
  if(action==='back-to-edit'){renderCreate();return;}
  if(action==='submit-create'){try{const po=service.create(draftItems,{actor,poDate:draftDate,key:createCommandKey});activeId=po.id;draftItems=[];createCommandKey='';formDirty=false;route='detail';notify('เปิดใบ PO ทดลองแล้ว ส่งให้เจ้าของพิจารณาได้');renderDetail();}catch(error){notify(error.message);}return;}
  if(action==='export'){actionButton.disabled=true;downloadPreviewReport(service.report(month,actor),month).then(()=>notify('สร้างไฟล์ Excel แล้ว')).catch(error=>notify(error.message)).finally(()=>{actionButton.disabled=false;});return;}
 if(action==='close'){reasonDialog('ยืนยันใบกำกับภาษีและปิด PO',null,'close',{invoice:true});return;}
 }
 const pageButton=event.target.closest('[data-page]');if(pageButton){listPage=Math.max(0,Number(pageButton.dataset.page));renderList();return;}
 const removeLine=event.target.closest('[data-remove-line]');if(removeLine){const form=root.querySelector('#preview-create-form'),index=Number(removeLine.dataset.removeLine);draftDate=form.querySelector('[name="po_date"]').value;draftItems=[...form.querySelectorAll('fieldset.preview-form-item')].map(fs=>collectForm(fs)).filter((_,i)=>i!==index);formDirty=true;renderCreate();return;}
 const itemButton=event.target.closest('[data-item-action]');if(itemButton){const po=currentPO(),item=po?.items.find(i=>i.id===itemButton.dataset.itemId);if(!po||!item)return;const action=itemButton.dataset.itemAction;if(action==='edit'){renderEdit(item,po);return;}const title=({approve:'อนุมัติซื้อรายการนี้?',approve_estimate:'อนุมัติวงเงินประมาณการ?',return:'ส่งรายการกลับพร้อมเหตุผล?',reject:'ไม่อนุมัติรายการนี้?',return_edit:'ขอแก้ไขและพักการอนุมัติรายการนี้?',request_revision:'ขอแก้ไขรายการนี้และพักการอนุมัติ?',unlock:'ปลดล็อกให้พนักงานแก้ไขรายการนี้?',refuse_revision:'ปฏิเสธคำขอและคงผลอนุมัติเดิม?',receive:'ยืนยันรับสินค้ารายการนี้แล้ว?'}[action]||'ยืนยันการดำเนินการ');if(action==='receive')reasonDialog(title,item,action,{receive:true});else reasonDialog(title,item,action);return;}
});
dialog.addEventListener('click',event=>{
 if(event.target.closest('[data-action="reload-latest"]')){formDirty=false;dialog.close();renderDetail();notify('โหลดข้อมูลล่าสุดแล้ว แบบฟอร์มที่ยังไม่ส่งถูกทิ้ง');return;}
 if(event.target.closest('[data-dialog-cancel]')){pendingNavigation=null;dialog.close();return;}
 if(event.target.closest('[data-action="discard-navigation"]')){const next=pendingNavigation;pendingNavigation=null;dialog.close();formDirty=false;draftItems=[];if(next)next();return;}
 if(event.target.closest('[data-action="reset-confirm"]')){service.reset();dialog.close();pendingNavigation=null;formDirty=false;draftItems=[];activeId='';route='list';notify('คืนชุดข้อมูลสังเคราะห์เริ่มต้นแล้ว');render();}
});
dialog.addEventListener('close',()=>{setTimeout(()=>{if(lastDialogTrigger?.isConnected)lastDialogTrigger.focus();else{const heading=root.querySelector('h1');if(heading){heading.tabIndex=-1;heading.focus();}}},0);});
render();
